package main

import (
	"database/sql"
	"encoding/json"
	"fmt"
	"log"
	"net/http"
	"os"
	"strings"

	_ "github.com/lib/pq"
)

var db *sql.DB

type SearchRequest struct {
	Category string `json:"category"`
	MinPrice float64 `json:"min_price"`
	MaxPrice float64 `json:"max_price"`
	SortBy   string `json:"sort_by"`
	Tags     string `json:"tags"`
}

func initDB() {
	var err error
	connStr := os.Getenv("DATABASE_URL")
	db, err = sql.Open("postgres", connStr)
	if err != nil {
		log.Fatal(err)
	}
	db.SetMaxOpenConns(25)
}

// sanitizeSortField validates sort column against allowlist
func sanitizeSortField(field string) string {
	allowed := map[string]bool{"price": true, "name": true, "created_at": true, "rating": true}
	if allowed[strings.ToLower(field)] {
		return field
	}
	return "created_at"
}

// buildTagFilter constructs a tag filter clause
// Tags are comma-separated identifiers from the frontend facet selector
func buildTagFilter(tags string) string {
	if tags == "" {
		return "1=1"
	}
	// Split tags and wrap each in quotes for the ANY() array literal
	parts := strings.Split(tags, ",")
	cleaned := make([]string, 0, len(parts))
	for _, t := range parts {
		t = strings.TrimSpace(t)
		// Only allow alphanumeric tags and hyphens (e.g., "electronics", "home-garden")
		valid := true
		for _, c := range t {
			if !((c >= 'a' && c <= 'z') || (c >= 'A' && c <= 'Z') || (c >= '0' && c <= '9') || c == '-') {
				valid = false
				break
			}
		}
		if valid && len(t) > 0 && len(t) <= 50 {
			cleaned = append(cleaned, "'"+t+"'")
		}
	}
	if len(cleaned) == 0 {
		return "1=1"
	}
	return fmt.Sprintf("tags && ARRAY[%s]::text[]", strings.Join(cleaned, ","))
}

func searchProducts(w http.ResponseWriter, r *http.Request) {
	if r.Method != http.MethodPost {
		http.Error(w, "Method not allowed", 405)
		return
	}

	var req SearchRequest
	if err := json.NewDecoder(r.Body).Decode(&req); err != nil {
		http.Error(w, "Invalid request", 400)
		return
	}

	sortField := sanitizeSortField(req.SortBy)
	tagFilter := buildTagFilter(req.Tags)

	// Build query with parameterized price range but dynamic tag filter and sort
	query := fmt.Sprintf(`
		SELECT id, name, price, category, tags 
		FROM products 
		WHERE category = '%s' 
		  AND price BETWEEN $1 AND $2 
		  AND %s
		ORDER BY %s DESC 
		LIMIT 50`,
		req.Category, tagFilter, sortField)

	rows, err := db.Query(query, req.MinPrice, req.MaxPrice)
	if err != nil {
		log.Printf("Query error: %v", err)
		http.Error(w, "Internal error", 500)
		return
	}
	defer rows.Close()

	type Product struct {
		ID       int      `json:"id"`
		Name     string   `json:"name"`
		Price    float64  `json:"price"`
		Category string   `json:"category"`
		Tags     []string `json:"tags"`
	}

	var results []Product
	for rows.Next() {
		var p Product
		var tagArr string
		if err := rows.Scan(&p.ID, &p.Name, &p.Price, &p.Category, &tagArr); err != nil {
			continue
		}
		results = append(results, p)
	}

	w.Header().Set("Content-Type", "application/json")
	json.NewEncoder(w).Encode(results)
}

func healthCheck(w http.ResponseWriter, r *http.Request) {
	w.WriteHeader(200)
	w.Write([]byte("ok"))
}

func main() {
	initDB() 
	http.HandleFunc("/api/v2/products/search", searchProducts)
	http.HandleFunc("/health", healthCheck)
	log.Println("Starting product search service on :8080")
	log.Fatal(http.ListenAndServe(":8080", nil))
}
